    public static readonly Quote[] Quotes = new Quote[]
    {
        new Quote { Id = "https://de.wikiquote.org/wiki/Verliebtheit", Text = "Das steht doch nicht bei einem selber, wen man lieb gewinnen soll.", Author = "Verliebtheit" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Verborgenheit", Text = "Die schönen Taten, welche in der Verborgenheit geschehen, sind die schönsten.", Author = "Verborgenheit" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Garten", Text = "Ach, die Liebe läßt das Menschenherz zum Pilzgarten werden, einem üppigen und unverschämten Garten, in dem geheimnisvolle und freche Pilze stehen", Author = "Garten" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Schminke", Text = "Die Lüge ist die Schminke auf dem Geist des Menschen.", Author = "Schminke" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Heinrich_Waggerl", Text = "Am auffälligsten unterscheiden sich die Leute darin, dass die Törichten immer wieder dieselben Fehler machen, die Gescheiten immer wieder neue.", Author = "Karl Heinrich Waggerl" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Vince_Ebert", Text = "Ohne den elektrischen Strom hätten wir innerhalb kürzester Zeit Zustände, wie sie noch nicht einmal im Odenwald vorkommen.", Author = "Vince Ebert" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_II._%28HRR%29", Text = "„Unsere Absicht ist aber in diesem Buch über die Falknerei, das, was ist, so zu zeigen, wie es ist, und als zuverlässige Kunst darzustellen; denn bisher fehlte es dabei sowohl an der Wissenschaft wie an der Kunst.", Author = "Friedrich II. (HRR)" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Klassenkampf", Text = "Der Geschlechterkampf ist so einfallslos wie der Klassenkampf.", Author = "Klassenkampf" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Dreschen", Text = "Was willst du dich das Stroh zu dreschen plagen?", Author = "Dreschen" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Ausruhen", Text = "Erquicklich ist die Mittagsruh, // Nur kommt man oftmals nicht dazu.", Author = "Ausruhen" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Jahreszeit", Text = "Man muss an alle Jahreszeiten denken.", Author = "Jahreszeit" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Bundesrepublik", Text = "Alles wird überlagert von der Vorstellung, dass dieses Land in Bedrängnis kommt, weil man zehn Euro pro Quartal beim Arzt abliefern soll. Als wenn das die Schicksalsfrage der Nation wäre.", Author = "Bundesrepublik" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Kurt_Lewin", Text = "Eine Forschung, die nichts anderes als Bücher hervorbringt, genügt nicht.", Author = "Kurt Lewin" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Ethik", Text = "Da liegt der entscheidende Punkt. Wir müssen uns klarmachen, daß alles ethisch orientierte Handeln unter zwei voneinander grundverschiedenen, unaustragbar gegensätzlichen Maximen stehen kann: es kann gesinnungsethisch oder verantwortungsethisch orientiert sein.", Author = "Ethik" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Schmetterling", Text = "Ein kleiner Spuk durch die Dampfheizung ging. // Keine Uhr war aufgezogen. // Ein zu früh geborener Schmetterling // Kam auf das Schachbrett geflogen.", Author = "Schmetterling" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Bistum", Text = "Der Papst ist ein Bischof wie ein anderer Bischof über sein Bistum und nichts weiter.", Author = "Bistum" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Japan", Text = "In Wahrheit ist Japan nur eine Erfindung. Ein solches Land und ein solches Volk gibt es nicht.", Author = "Japan" },
        new Quote { Id = "https://de.wikiquote.org/wiki/CSU", Text = "Die CSU und ihre Führung muss den Stolz der Bayern verkörpern. Das ist der entscheidende Maßstab.", Author = "CSU" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Kopf", Text = "Das Mainstream-Kino entrealisiert, überdreht oder ironisiert Gewalt. „Pulp Fiction ist dafür ein Musterbeispiel. Wenn da der Kopf weggeblasen wird, herrscht ein Riesengelächter im Saal. Das ist perfekt gemachter Zynismus im Dienste der Verkaufbarkeit.", Author = "Kopf" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Burg", Text = "Mein Heim ist meine Burg.", Author = "Burg" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Zerst%C3%B6rung", Text = "Alles Denken ist unmoralisch. Sein eigentliches Wesen ist Zerstörung. Wenn Sie über etwas nachdenken, töten Sie es.", Author = "Zerstörung" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Norbert_Bolz", Text = "Der fanatische Feminismus ist eine psychische Epidemie, eine Geisteskrankheit, die aufgrund ihrer massenweisen Verbreitung in gewissen Medien und Bildungsanstalten als neue Form von Intelligenz gefeiert wird.", Author = "Norbert Bolz" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Erbschaft", Text = "Damit er einst was kann von seinen Eltern erben, so lassen sie ihn jetzt vor Hunger weislich sterben.", Author = "Erbschaft" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Edward_Abbey", Text = "Wachstum um des Wachstums willen ist die Ideologie der Krebszelle.", Author = "Edward Abbey" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Gerhard_Frey", Text = "Ich bin tatsächlich der einzige Parteivorsitzende seit Gründung der Bundesrepublik, der seine Partei finanziert.", Author = "Gerhard Frey" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Robert_Frost", Text = "Bildung ist die Fähigkeit, fast alles anhören zu können, ohne die Ruhe zu verlieren oder das Selbstvertrauen.", Author = "Robert Frost" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Paolo_Conte", Text = "Jurisprudenz und Musik - das eine kann so disharmonisch und asynchron sein wie das andere.", Author = "Paolo Conte" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Norbert_Elias", Text = "Die ‚Umstände‘, die sich ändern, sind nichts, was gleichsam von ‚außen‘ an den Menschen herankommt; die ‚Umstände‘, die sich ändern, sind die Beziehungen zwischen den Menschen selbst. Der Mensch ist ein außerordentlich modellierbares und variables Wesen [...].", Author = "Norbert Elias" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Format", Text = "Wer sagt, daß Mörder Format haben?", Author = "Format" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Mahatma_Gandhi", Text = "Dem Verstand Allwissenheit zuzuschreiben, ist die gleiche Art von Götzendienst, wie die Anbetung von Stock und Stein. Ich plädiere nicht für eine Abwertung der Vernunft, aber für die gebührende Anerkennung der Instanz in uns, die die Vernunft heiligt.", Author = "Mahatma Gandhi" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Knabe", Text = "Ach, besser wär's, ihr alten Knaben, ein Rückgrat überhaupt zu haben im Leben und daheim im Laden und nicht bei völkischen Paraden.", Author = "Knabe" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Rupertus_Meldenius", Text = "Im Notwendigen Einheit, im Zweifel Freiheit, in allem Liebe.", Author = "Rupertus Meldenius" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Ruth_Dreifuss", Text = "Armut beschämt nicht die betroffenen Menschen, Armut beschämt die Gesellschaft.", Author = "Ruth Dreifuss" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Enrique_Pe%C3%B1alosa", Text = "Ob eine Stadt zivilisiert ist, hängt nicht von der Zahl ihrer Autobahnen und Schnellstraßen ab, sondern davon, ob ein Kind auf dem Dreirad unbeschwert und sicher überall hinkommt.", Author = "Enrique Peñalosa" },
        new Quote { Id = "https://de.wikiquote.org/wiki/%C3%9Cbereinstimmung", Text = "Der Kürze halber möchte ich die Definition geben, daß die Schönheit eine bestimmte gesetzmäßige Übereinstimmung aller Teile, was immer für eine Sache, sei, die darin besteht, daß man weder etwas hinzufügen noch hinwegnehmen könnte, ohne sie weniger gefällig zu machen.", Author = "Übereinstimmung" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Gauner", Text = "Um einen Gauner zu erkennen, braucht es anderthalb Gauner.", Author = "Gauner" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Heer", Text = "Der Radiumkondensator ist erfunden. Mit von Wolkenhöhen herab gesandten Radiumstrahlenbündeln in ein paar Minuten feindliche Flotten und Heere zu vernichten, ist ein Kinderspiel.", Author = "Heer" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Helmut_Seethaler", Text = "Bekommt man Dinge, bemerkt man es gleich. Bekommt man Werte, bemerkt man es erst, wenn man sich mit ihnen bewähren muß.", Author = "Helmut Seethaler" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Paul_Val%C3%A9ry", Text = "Die Geschichte rechtfertigt, was immer man will. Sie lehrt schlechterdings nichts, denn es gibt nichts, was sich mit ihr nicht beweisen ließe.", Author = "Paul Valéry" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Selbsterkenntnis", Text = "Allen Menschen ist es gegeben, sich selbst zu erkennen und klug zu sein.", Author = "Selbsterkenntnis" },
        new Quote { Id = "https://de.wikiquote.org/wiki/%C3%9Cbernahme", Text = "Auch für den Klugen ist doch keine Schande, statt sich zu übernehmen, viel zu lernen.", Author = "Übernahme" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Cool", Text = "Ich scheine einfach für alle Zeiten ein Prototyp zu sein. Das Image des coolen Vamps werde ich jedenfalls nicht los. Egal, wie viele Neurotikerinnen ich spiele, ich bleibe diejenige, die die Kontrolle hat.", Author = "Cool" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Lebensweg", Text = "Alles das, woran ich auf Erden gelitten habe und was mir am Menschen böswillig und gehässig erschien, brüchig und gemein, machtwillig oder eitel, alles das begegnete mir auf meinem Lebenswege stets im Gewande der Ideale.", Author = "Lebensweg" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Artikel", Text = "Die wirklich guten Artikel in unserer Enzyklopädie wurden von einem oder zwei Autoren geschrieben.", Author = "Artikel" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Ludwig_Marcuse", Text = "Da man Macht haben muss, um das Gute durchzusetzen, setzt man zunächst das Schlechte durch, um Macht zu gewinnen.", Author = "Ludwig Marcuse" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Bed%C3%BCrfnis", Text = "Alles, was uns der Bedürfnis überhebt, zu leeren Räumen unsere Zuflucht zu nehmen, ist wirklicher Gewinn für die Naturwissenschaft.", Author = "Bedürfnis" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Literatur", Text = "Als ein literarisches Denkmal steht so der Koran als einzigartige Schöpfung in der arabischen Literatur ohne Vorläufer noch Nachfolger in einer ihm eigenen Sprache da. Muslime aller Zeiten sind sich einig, die Unnachahmlichkeit nicht nur des Inhalts, sondern auch des Stiles zu bekräftigen.", Author = "Literatur" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Hans_Kelsen", Text = "Demokratie kann sich nicht dadurch verteidigen, daß sie sich selbst aufgibt.", Author = "Hans Kelsen" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Sabine_B%C3%A4tzing", Text = "Tabakkonsum ist das größte vermeidbare Gesundheitsrisiko unserer Zeit.", Author = "Sabine Bätzing" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Hans_Peter_Dreitzel", Text = "Der Mensch ist ein leidendes Wesen, daran besteht kein Zweifel.", Author = "Hans Peter Dreitzel" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Heidentum", Text = "Das Heidentum hielt den am Höchsten, der die meisten Vorzüge, das Christentum den, der die wenigsten Fehler hat.", Author = "Heidentum" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Teich", Text = "Der Großmütige gleicht einem Mann, der mit seinem Abendbrot Fische fütterte, aus Unachtsamkeit in den Teich fiel und ersoff.", Author = "Teich" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Jupiter", Text = "Alle Schöpfung ist Werk der Natur. Von Jupiters Throne // Zuckt der allmächtige Strahl, nährt und erschüttert die Welt.", Author = "Jupiter" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Sph%C3%A4re", Text = "Beethoven begreift in sich die ganze, runde, komplexe Menschennatur. Niemals hat ein Musiker von der Harmonie der Sphären, dem Zusammenklang der Gottesnatur, mehr gewußt und mehr erlebt als Beethoven.", Author = "Sphäre" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Fr%C3%B6hlichkeit", Text = "Das Beste, was wir auf der Welt tun können, ist Gutes tun, fröhlich sein und die Spatzen pfeifen lassen.", Author = "Fröhlichkeit" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Musik", Text = "Alle Musik wird geboren im Herzen der Menschen.", Author = "Musik" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Sergej_Lukianenko", Text = "Denn jeder Schritt der Menschheit ins Morgen stellt eine Verletzung der Gesetze von heute dar.", Author = "Sergej Lukianenko" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Thomas_Spitzer", Text = "Die Welt ist eine Heilanstalt, // mit lauter schweren Fällen, // die alle glauben frei zu sein, // in ihren Gummizellen.", Author = "Thomas Spitzer" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Weiblichkeit", Text = "Alles Vergängliche // Ist nur ein Gleichnis // Das Unzulängliche, // Hier wirds Ereignis; // Das Unbeschreibliche, // Hier ist es getan; // Das Ewig-Weibliche // Zieht uns hinan.", Author = "Weiblichkeit" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Eichh%C3%B6rnchen", Text = "Was für die junge Braut der Kranz // Und für das Kirchenlicht der Kragen, // Das ist auch noch in unsern Tagen // Dem Eichhorn und dem Fuchs der Schwanz.", Author = "Eichhörnchen" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Abneigung", Text = "Alles, was man denkt, ist entweder Zuneigung oder Abneigung!", Author = "Abneigung" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Perspektive", Text = "Das wahrhaft schöpferische, geniale Kunststück, Gemeinschaft und Persönlichkeit in der Menschengestaltung zu vereinen, hat bisher unsere Epik nur höchst unvollkommen zustande gebracht. In dieser Vereinigung aber erblicken wir die Perspektive einer neuen Romanliteratur.", Author = "Perspektive" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Wasserwaage", Text = "Wenn man erkennen will, ob etwas eben und gerade ist, so gebraucht man Wasserwaage und Richtschnur. Wenn man erkennen will, ob etwas rund oder rechteckig ist, so gebraucht man Zirkel und Winkelmaß. Wenn ein Herrscher sich selbst kennen lernen will, so braucht er aufrichtige Staatsmänner.", Author = "Wasserwaage" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Findet_Nemo", Text = "Drehbuch: Andrew Stanton", Author = "Findet Nemo" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Automat", Text = "Der Despotismus forderte Automaten; - und Priester und Leviten waren fühllos genug, sie ihm aus Menschen zu schnitzen.", Author = "Automat" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Ernte", Text = "Etwas Kurz-Gesagtes kann die Frucht und Ernte von vielem Lang-Gedachten sein.", Author = "Ernte" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Herr_Lehmann", Text = "Drehbuch: Sven Regener", Author = "Herr Lehmann" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Obst", Text = "Bio-Obst per e-mail zu bestellen ist mein Luxus.", Author = "Obst" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Gebet", Text = "Bet und arbeit! ruft die Welt, // Bete kurz! denn Zeit ist Geld. // An die Türe pocht die Not - // Bete kurz! denn Zeit ist Brot.", Author = "Gebet" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Gerechtigkeit", Text = "Barmherzigkeit ist leichter zu üben als Gerechtigkeit.", Author = "Gerechtigkeit" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Ralf_Dahrendorf", Text = "Berlin ist die Stadt, in der ich groß geworden bin. Sie repräsentiert das lebendige gegenwärtige Deutschland. Sie ist bei Londonern sehr beliebt, auch bei Leuten aus Paris oder Rom. Für die, die hierher kommen, besonders für die Ausländer, ist Berlin wirklich eine Metropole.", Author = "Ralf Dahrendorf" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Mark_Twain", Text = "Adam war ein Mensch - das erklärt alles. Er wollte den Apfel nicht des Apfels wegen, sondern nur, weil er verboten war.", Author = "Mark Twain" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Schw%C3%A4rmerei", Text = "Denn Schwärmerey steckt wie der Schnuppen an. // Man fühlt, ich weis nicht was, und eh man wehren kann, // Ist unser Kopf des Herzens nicht mehr mächtig.", Author = "Schwärmerei" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Funktion", Text = "Alle Menschen sind Intellektuelle, […] aber nicht alle Menschen haben in der Gesellschaft die Funktion von Intellektuellen.", Author = "Funktion" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Stanley_Eddington", Text = "Bis zu den Sternen und darüber hinaus ist die Welt mit Äther erfüllt. Er durchdringt die Räume zwischen Atomen. Äther ist überall. [...] Es gibt keinen Raum ohne Äther, und keinen Äther, der keinen Raum einnimmt.", Author = "Arthur Stanley Eddington" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Lyndon_B._Johnson", Text = "John Kennedy wurde ermordet, und auch ich werde ermordet (...) der einzige Unterschied ist: Ich lebe.", Author = "Lyndon B. Johnson" },
        new Quote { Id = "https://de.wikiquote.org/wiki/T%C3%A4towierung", Text = "Der moderne Mensch, der sich tätowiert, ist ein Verbrecher oder ein Degenerierter.", Author = "Tätowierung" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Tennis", Text = "Der Tennisplatz ist eine Landkarte, und man muss die richtigen Stellen kennen, von denen aus man den Punkt macht, oder wie ich es nenne: den Ball tötet. Es ist egal, ob es der zweite oder zehnte Ball ist, die Stelle muss stimmen.", Author = "Tennis" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Kamo_no_Ch%C5%8Dmei", Text = "Am Morgen gestorben, am Abend geboren, das ist das Geschick des Menschen - gleich den Schaumblasen auf dem Wasser. Und dieser Mensch, der geboren wird und stirbt, wer weiß schon, woher er kommt, wohin er geht?", Author = "Kamo no Chōmei" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Leo_Kirch", Text = "Wenn ich die gleiche Entrüstung erlebt hätte, als Helmut Kohl seine Deals mit Leo Kirch gemacht hat, würde ich ihre Empörung über Gerhard Schröders Übereinkunft mit Gasprom herzlich gern teilen. So aber halte ich das für eine etwas künstliche Aufregung.", Author = "Leo Kirch" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Ungebildet", Text = "Lenin sagte einmal, der ungebildete Mensch stehe außerhalb der Politik. Heute aber haben wir ein gebildetes Volk. Wie wir in den letzten Jahren handelten, bedeutete, es aus der Politik herauszuhalten. Das ist eine Mißachtung des Volkes. Das ist eine Art Elitedenken.", Author = "Ungebildet" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Knoblauch", Text = "Isst man die Keime mit, schläft man garantiert schlecht.", Author = "Knoblauch" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Klee_%28Pflanze%29", Text = "Lebe, mein Rappe, um Klee zu fressen.", Author = "Klee (Pflanze)" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Albanische_Sprichw%C3%B6rter", Text = "Der Wolf beißt fremdes Fleisch, das eigene leckt er.", Author = "Albanische Sprichwörter" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Richtig", Text = "Echtheit der Gefühle, die man im Herzen trägt, Richtigkeit und Wahrheit der Gedanken, die man beide auf seine Hörer übertragen will, geben die sicherste Gewähr, dass der Redner wirkungsvoll spricht.", Author = "Richtig" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Buchdruck", Text = "Die Erfindung der Buchdrukkerkunst macht dem menschlichen Verstande zwar Ehre, doch verliert sie sehr, wenn man sie mit der Erfindung der Buchstaben vergleicht.", Author = "Buchdruck" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_von_Wieser", Text = "Die Menschen stehen unter dem Gesetze der Macht.", Author = "Friedrich von Wieser" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Ulrich_von_Brockdorff-Rantzau", Text = "Es wird von uns verlangt, dass wir uns als die Alleinschuldigen bekennen; ein solches Bekenntnis wäre in meinem Munde eine Lüge. - Rede am 7. Mai 1919 vor der Interallierten Militärkommission zu Beginn der Friedensverhandlungen von Versailles, welt.de", Author = "Ulrich von Brockdorff-Rantzau" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Bogumil_Goltz", Text = "[...] das Weib trachtet unendlich mehr danach, glücklich zu machen, als glücklich zu sein;", Author = "Bogumil Goltz" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Neutralit%C3%A4t", Text = "Beladet euch nicht mit fremden Angelegenheiten, bündet euch nicht mit fremder Herrschaft, seid auf der Hut vor Zweigung und Eigennutz. Hütet euer Vaterland, haltet zu ihm. Pflegt nicht vorsätzliche Kriegslust. Wenn euch aber jemand überfällt, dann streitet tapfer für Freiheit und Vaterland.", Author = "Neutralität" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Zuversicht", Text = "Jede Freude füllt, jeder Schmerz leert dich, aber in jener hat noch Sehnsucht Platz, in diesem noch Zuversicht.", Author = "Zuversicht" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Klaus_Wowereit", Text = "Berlin ist arm, aber sexy.", Author = "Klaus Wowereit" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Mike_Huckabee", Text = "Jesus ist viel zu schlau, als dass er sich jemals für ein öffentliches Amt bewerben würde.", Author = "Mike Huckabee" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Keuschheit", Text = "Armut, Keuschheit und Gehorsam, - drei Gelübde, deren jedes, einzeln betrachtet, der Natur das unausstehlichste scheint, so unerträglich sind sie alle.", Author = "Keuschheit" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Fridtjof_Nansen", Text = "Ich glaube, daß, wenn wir auf die sich in der Natur selbst vorfindenden Kräfte Acht geben und versuchen, mit denselben und nicht gegen sie zu arbeiten, wir den sichersten und leichtesten Weg zum Pole finden werden.", Author = "Fridtjof Nansen" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Tal", Text = "Erklimme das Gebirge oder steige ins Tal hinab, gehe bis ans Ende der Welt oder um dein Haus herum: du triffst immer nur dich auf den Straßen des Zufalls.", Author = "Tal" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Gleichgewicht", Text = "Dann, ja dann müsste alles aus dem Gleichgewicht kommen und die Welt in ein Chaos sich verwandeln, wenn nicht der nämliche Geist der Harmonie und Liebe sie erhielte, der auch uns erhält.", Author = "Gleichgewicht" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Gottfried_August_B%C3%BCrger", Text = "Amors Pfeil hat Widerspizen. // Wen er traf, der lass' ihn sizen, // Und erduld' ein wenig Schmerz!", Author = "Gottfried August Bürger" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Kunst", Text = "Aber freilich leuchtet der Menschengeist am hellsten, wo Glanz der Kunst mit Glanz der Wissenschaft sich eint.", Author = "Kunst" },
        new Quote { Id = "https://de.wikiquote.org/wiki/B%C3%BCgeleisen", Text = "Alles Billige erweist sich schließlich als teuer. Das gilt für Bügeleisen wie für Frauen.", Author = "Bügeleisen" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Maximilian_Scheer", Text = "Freunde sprechen miteinander in achtungsvoller Offenheit.", Author = "Maximilian Scheer" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Anpassung", Text = "Anpassung fordert die Welt, Charakter will sich verweigern. Das Unversöhnliche eint heitere Resignation.", Author = "Anpassung" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Kylie_Minogue", Text = "Ich kann meine alten Videos nicht mehr anschauen, ohne mich zu schämen. Schwulenikonen haben normalerweise ein tragisches Leben. Ich hatte bloß tragische Frisuren und Outfits.", Author = "Kylie Minogue" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Thomas_Jefferson", Text = "Am Altar Gottes habe ich in jeder Form der Tyrannei über die Menschen ewige Feindschaft geschworen.", Author = "Thomas Jefferson" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Christian_K%C3%A4mmerling", Text = "Es gibt Revolutionen, die machen die Welt komplizierter, und es gibt Revolutionen, die machen die Welt einfacher. Und es gibt Revolutionen, die machen die Welt auf komplizierte Art einfacher. Dazu gehört das Telefon.", Author = "Christian Kämmerling" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Sebastian_Kneipp", Text = "Wenn du merkst, du hast gegessen, hast du schon zu viel gegessen.", Author = "Sebastian Kneipp" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Pietro_Metastasio", Text = "Wenn die Gerechtigkeit all ihre Strenge anwendete, würde die Erde bald eine Wüste sein.", Author = "Pietro Metastasio" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Wiglaf_Droste", Text = "Der Partnerlook ist die Sichtbarmachung der Enteierung des Mannes.", Author = "Wiglaf Droste" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Alvin_Toffler", Text = "Der Zukunftsschock ist eine Zeiterscheinung, ein Ergebnis der Tatsache, dass sich die Veränderungen in der Gesellschaft immer rascher vollziehen, einen immer größeren Umfang annehmen.", Author = "Alvin Toffler" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Margaret_Thatcher", Text = "Wir haben aufgehört, eine Nation auf dem Rückzug zu sein.", Author = "Margaret Thatcher" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Angebliche_%22indianische_Sprichw%C3%B6rter%22_aus_Nordamerika", Text = "Erst wenn der letzte Baum gerodet, der letzte Fluss vergiftet, der letzte Fisch gefangen ist, werdet Ihr merken, dass man Geld nicht essen kann.", Author = "Angebliche \"indianische Sprichwörter\" aus Nordamerika" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Gro%C3%9Fmutter", Text = "Als der Großvater die Großmutter nahm, wusste man nichts von Mamsell und Madam.", Author = "Großmutter" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Fahren", Text = "Der durchschnittliche Tourist möchte dorthin fahren, wo es keine Touristen gibt.", Author = "Fahren" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Bericht", Text = "Der Bericht über meinen Tod wurde stark übertrieben.", Author = "Bericht" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Werner_Maihofer", Text = "Absolute Sicherheit heißt absolute Unfreiheit. Absolute Freiheit heißt absolute Unsicherheit. Die liberale Position: die richtige Mitte. Und im Konflikte zwischen Sicherheit und Freiheit: in dubio pro libertate. Im Zweifel für die Freiheit.", Author = "Werner Maihofer" },
        new Quote { Id = "https://de.wikiquote.org/wiki/U", Text = "Jemand ein X für ein U vormachen.", Author = "U" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Werden", Text = "Aus Fluch wird Fluch.", Author = "Werden" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Demut", Text = "Andacht, die Demut nicht begleitet, wird unfehlbar Stolz.", Author = "Demut" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Erwin_Kr%C3%A4utler", Text = "Dass die Befreiungstheologie tot sei, ist ein kompletter Unsinn. Unter Befreiungstheologie verstehe ich jene Theologie, die aus einem Gottesverständnis geboren worden ist. Es geht um jenen Gott, der gesagt hat, ich habe den Schrei meines Volkes gehört. Er sagt es zweimal.", Author = "Erwin Kräutler" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Haustier", Text = "Da das Halten wilder Tiere gesetzlich verboten ist und die Haustiere mir kein Vergnügen machen, so bleibe ich lieber unverheiratet.", Author = "Haustier" },
        new Quote { Id = "https://de.wikiquote.org/wiki/H%C3%B6hle", Text = "In des Waldes finstern Gründen // Und in Höhlen tief versteckt // Ruht der Räuber allerkühnster, // Bis ihn seine Rosa weckt.", Author = "Höhle" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Rationalisierung", Text = "Das Glück ist ein Mysterium wie die Religion und duldet kein Rationalisieren.", Author = "Rationalisierung" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Macht", Text = "Aber den Religionen – ob Katholizismus oder Judentum – geht es ja ohnehin nicht um Gott oder um die Geheimnisse des Lebens. Es geht um Geld und politische Macht.", Author = "Macht" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Prophet", Text = "Das Weib will Propheten, weil es auch im Denken sich hingeben, das heißt glauben will.", Author = "Prophet" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Marie_von_Ebner-Eschenbach", Text = "Alberne Leute sagen Dummheiten, gescheite Leute machen sie.", Author = "Marie von Ebner-Eschenbach" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Schwangerschaft", Text = "Wenn Männer schwanger werden könnten, wäre die Abtreibung längst ein Sakrament.", Author = "Schwangerschaft" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Monolog", Text = "Denn was nicht gesellig gesungen werden kann, ist wirklich kein Gesang, wie ein Monolog kein Drama.", Author = "Monolog" },
        new Quote { Id = "https://de.wikiquote.org/wiki/C%C3%A9sar_Luis_Menotti", Text = "Sie können sich in Spanien nicht entscheiden, ob sie sich am Stier oder am Torero orientieren sollen.", Author = "César Luis Menotti" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Aldous_Huxley", Text = "Die größten Triumphe der Propaganda wurden nicht durch Handeln, sondern durch Unterlassung erreicht. Groß ist die Wahrheit, größer aber, vom praktischen Gesichtspunkt, ist das Verschweigen von Wahrheit.", Author = "Aldous Huxley" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Ungarische_Sprichw%C3%B6rter", Text = "Ende Gut, alles Gut.", Author = "Ungarische Sprichwörter" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Ferdinand_Foch", Text = "Das ist kein Frieden. Es ist ein Waffenstillstand auf 20 Jahre.", Author = "Ferdinand Foch" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Hans-Olaf_Henkel", Text = "Mathematik ist nicht alles, aber ohne Mathematik ist alles nichts.", Author = "Hans-Olaf Henkel" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Hoffnung", Text = "Alle menschliche Weisheit liegt in den zwei Worten Harren und Hoffen!", Author = "Hoffnung" },
        new Quote { Id = "https://de.wikiquote.org/wiki/M%C3%A4nner_%C3%BCber_M%C3%A4nner", Text = "Alle Frauen werden wie ihre Mütter, das ist ihre Tragödie. Kein Mann wird wie seine Mutter, das ist seine Tragödie.", Author = "Männer über Männer" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Gotthilf_Fischer", Text = "Fast. Wer nicht singen kann, darf den Flügel wegschieben oder die Noten verteilen.", Author = "Gotthilf Fischer" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Bedeutungslosigkeit", Text = "Jeder ist immer erreichbar. Die ganze Welt beschleunigt sich, alles ist dringend, und wo alles dringend ist, ist nichts mehr dringend, und damit schlittern wir in eine Bedeutungslosigkeit hinein.", Author = "Bedeutungslosigkeit" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Gefangenschaft", Text = "Gefangenschaft ist eine Art Schlaf. Das Leben geht unbemerkt weiter, denn richtig lebendig fühlen wir uns nur, wenn wir alle unsere Fähigkeiten auch nutzen können.", Author = "Gefangenschaft" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Rechtfertigung", Text = "Denn der eigentliche Gegenstand der Theologie ist der der Sünde schuldige Mensch und der rechtfertigende Gott und Heiland dieses Sünders. Was außer diesem Gegenstand in der Theologie gesucht und verhandelt wird, ist Irrtum und Gift.", Author = "Rechtfertigung" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Unkraut", Text = "Am meisten Unkraut trägt der fetteste Boden.", Author = "Unkraut" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Truman_Capote", Text = "Ich bin schwul. Ich bin süchtig. Ich bin ein Genie.", Author = "Truman Capote" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Laterne", Text = "Ein geistreicher Mann ist verloren, wenn er nicht auch ein Mann von energischem Charakter ist. Hat man die Laterne des Diogenes, so muss man auch des Diogenes Stock haben.", Author = "Laterne" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Italo_Svevo", Text = "Die Toten waren niemals Sünder.", Author = "Italo Svevo" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Wien", Text = "Der Tod, das muss ein Wiener sein.", Author = "Wien" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Clown", Text = "Der Feierabend des Nichtkünstlers ist die Arbeitszeit eines Clowns.", Author = "Clown" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Ministerium", Text = "Bis ins Krankenhaus oder bis ins Ministerium; dahin kommen alle körperlich und geistig ruinierten Leute.", Author = "Ministerium" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Geselligkeit", Text = "Je verbreiteter die Geselligkeit, desto frostiger die Herzen.", Author = "Geselligkeit" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Peter_Terium", Text = "Dass wir die Solar-Technik lange komplett abgelehnt haben, war aus heutiger Sicht ein Fehler.", Author = "Peter Terium" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Thomas_Osterkorn", Text = "Gerhard Schröders großes Verdienst ist und bleibt, daß er Deutschland aus dem rechtlich fragwürdigen und politisch abenteuerlichen Krieg der USA im Irak herausgehalten hat. Allein schon dafür hat er einen Platz in den Geschichtsbüchern verdient.", Author = "Thomas Osterkorn" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Paul_de_Lagarde", Text = "Die Kirche Roms hat durch die Einführung des Weihnachtsfestes das Christenthum gerettet.", Author = "Paul de Lagarde" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Ottfried_Fischer", Text = "Ich bin froh, dass ich mit meiner Breite aus den Einheitsgesichtern im Fernsehen heraussteche. Mit mir können sich die Leute viel besser identifizieren als mit einem Schönling.", Author = "Ottfried Fischer" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Albert_Brooks", Text = "Wir geben ungeheure Mengen dafür aus, andere zu attackieren. Warum fliegen wir nicht 20 000 Botschafter des guten Willens in die arabische Welt und laden die Jungs dort drüben zum Essen ein, warum schicken wir keine Schmuse-Corps?", Author = "Albert Brooks" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Bernhard_Bueb", Text = "Ein Kind kann tyrannischen Eltern weder physisch noch psychisch standhalten, nicht einmal seine Gedanken sind frei.", Author = "Bernhard Bueb" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Josef_Joffe", Text = "Versuche nie durch Konspiration zu erklären, was auf Chaos oder Inkompetenz zurückgeführt werden muss.", Author = "Josef Joffe" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Liegen", Text = "Die Mühen der Gebirge liegen hinter uns // Vor uns liegen die Mühen der Ebenen.", Author = "Liegen" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Wolfgang_Dvorak-Stocker", Text = "Gemessen an ihren Verbrechen waren Hitler und Stalin auf gleicher Augenhöhe, nur dass der eine den Krieg gewonnen hat. Das NS-Regime ist nicht an seinen Verbrechen, sondern an seiner Dummheit gescheitert.", Author = "Wolfgang Dvorak-Stocker" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Aufhebung", Text = "Fortschritt in eine Richtung kommt nicht ohne Aufhebung der Möglichkeit zum Fortschritt in andere Richtung zustande.", Author = "Aufhebung" },
        new Quote { Id = "https://de.wikiquote.org/wiki/John_Ruskin", Text = "Es gibt kaum etwas auf dieser Welt, das nicht irgend jemand ein wenig schlechter machen und etwas billiger verkaufen könnte, und die Menschen, die sich nur am Preis orientieren, werden gerechte Beute solcher Machenschaften.", Author = "John Ruskin" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Fr%C3%A9d%C3%A9ric_Chopin", Text = "Mutter, meine arme Mutter.", Author = "Frédéric Chopin" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Rheinland-Pfalz", Text = "Gott schütze Rheinland-Pfalz!", Author = "Rheinland-Pfalz" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Laurence_Sterne", Text = "Auch jetzt im Augenblick sollte jeder Gebildete Sternes Werke wieder zur Hand nehmen, damit auch das 19. Jahrhundert erführe, was wir ihm schuldig sind, und einsähe, was wir ihm schuldig werden können.", Author = "Laurence Sterne" },
        new Quote { Id = "https://de.wikiquote.org/wiki/H%C3%BClle", Text = "Die Natur hat es an sich, in ihren gröbsten Hüllen immer das Edelste zu verstecken, und der eigentliche Tod ist ganz gewiss das Non plus ultra der Wollust.", Author = "Hülle" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Redner", Text = "Allein der Vortrag macht des Redners Glück.", Author = "Redner" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Evelyn_Hamann", Text = "Liebe Evelyn! Dein Timing war immer perfekt - nur heute hast Du die Reihenfolge nicht eingehalten. Na warte!", Author = "Evelyn Hamann" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Neigung", Text = "Den Kindern rate ich, ihr eigenes Leben zu führen, gegen mich zu rebellieren und ihre Neigungen zu entdecken.", Author = "Neigung" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Bleistift", Text = "Ein Zensor ist ein menschgewordener Bleistift oder ein bleistiftgewordener Mensch, ein fleischgewordener Strich über die Erzeugnisse des Geistes, ein Krokodil, das an den Ufern des Ideenstromes lagert und den darin schwimmenden Literaten die Köpf' abbeißt.", Author = "Bleistift" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Isolierung", Text = "Vom Standpunkt des Barbaren ist die Freiheit gleichbedeutend mit Isolierung.", Author = "Isolierung" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Journalist", Text = "Als ich am Kanzler vorbeikam, stand er auf, winkte mir zu und ich winkte zurück. Ich denke, die Journalisten zeigten schlechten Geschmack, als sie den Mann der Stunde in Deutschland kritisierten.", Author = "Journalist" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Intrige", Text = "Der Notar ist der weltliche Beichtvater. Er ist Puritaner von Profession, und Ehrlichkeit, sagt Shakespeare, ist kein Puritaner. Er ist zugleich der Kuppler für alle möglichen Zwecke, der Lenker der bürgerlichen Intrigen und Kabalen.", Author = "Intrige" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Legitimation", Text = "Die Legitimation der Wehrpflicht muss sehr sorgfältig geprüft werden, da sie die intensivste Inpflichtnahme des Staates bedeutet. Es bedarf hierzu einer sorgsamen Beobachtung der Rahmenbedingungen. Dazu gehört auch das Gebot der Einhaltung der Wehrgerechtigkeit.", Author = "Legitimation" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Athen", Text = "Es gibt drei Hügel, von denen das Abendland seinen Ausgang genommen hat: Golgatha, die Akropolis in Athen, das Capitol in Rom. Aus allen ist das Abendland geistig gewirkt, und man darf alle drei, man muss sie als Einheit sehen.", Author = "Athen" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Regisseur", Text = "Politiker sind Schauspieler ohne Drehbuch, ohne einen Regisseur, der alles zusammenhält.", Author = "Regisseur" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Schwachheit", Text = "Ausdauer ist eine Tochter der Kraft, Hartnäckigkeit eine Tochter der Schwäche, nämlich - der Verstandesschwäche.", Author = "Schwachheit" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Internet", Text = "Am Ende des Internets ist Energie.", Author = "Internet" },
        new Quote { Id = "https://de.wikiquote.org/wiki/F%C3%A4ulnis", Text = "Etwas ist faul im Staate Dänemark!", Author = "Fäulnis" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Schreiben", Text = "Acht Bände hat er geschrieben. Er hätte gewiss besser getan er hätte acht Bäume gepflanzt oder acht Kinder gezeugt.", Author = "Schreiben" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Auge", Text = "Ach, deine Augen droh'n mir mehr Gefahr als zwanzig ihrer Schwerter. Blickst du mich aber freundlich an, so bin ich gegen ihre Rachsucht gestählt. Durch ihren Hass zu sterben wäre mir jedoch besser, als ohne deine Liebe ein verhaßtes Leben weiterzuleben.", Author = "Auge" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Heinrich_Wackenroder", Text = "Beym Steigen, beym Sinken der Sonne, beym Schimmer des Mondes ist die Natur in einer raschen, unwillkührlichen Entzückung, in der sie noch freygebiger ist, noch weniger spart, und wie ein Pfau in stolzer Pracht allen Schmuck mit inniger Fraude rauschend aus einanderschlägt.", Author = "Wilhelm Heinrich Wackenroder" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Ausdauer", Text = "Aber der Friede erfordert unentwegen, zähen, dauernden Dienst, er verlangt Ausdauer, erlaubt keinen Zweifel.", Author = "Ausdauer" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Golda_Meir", Text = "Moses schleppte uns 40 Jahre durch die Wüste, um uns an den einzigen Ort im Nahen Osten zu bringen, an dem es kein Öl gibt.", Author = "Golda Meir" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Seuche", Text = "Anders gesagt: Hunger, Seuchen, Durst und andere armutsbedingte Lokalkonflikte zerstören jedes Jahr fast genauso viele Männer, Frauen und Kinder wie der Zweite Weltkrieg in sechs Jahren. Für die Menschen der Dritten Welt ist der Dritte Weltkrieg unzweifelhaft in vollem Gang.", Author = "Seuche" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Eiche", Text = "Die Axt erklingt, da blinkt schon jedes Beil, // Die Eiche fällt, und jeder holzt sein Teil.", Author = "Eiche" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Anerkennung", Text = "Anerkennung geht in der Regel nur so weit, als sie dazu dient, dem Anerkennenden selbst Relief zu geben.", Author = "Anerkennung" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Meinungsfreiheit", Text = "Als die Verfassung in den Niederlanden entstand, herrschte eine Kultur mit einem strengen Ehrenkodex. Es gab zwar die freie Meinungsäußerung, aber auch das Duell.", Author = "Meinungsfreiheit" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Indolenz", Text = "Die Lebensregungen des strebsamen Jüngers waren von Kind an darauf gerichtet, ein Großer zu werden. Seine Gleichgültigkeit in der Schule, die miserablen Zeugnisse, die Indolenz gegenüber den praktischen Dingen des Lebens durften niemanden täuschen.", Author = "Indolenz" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Wilhelm_Hey", Text = "Alle Jahre wieder // Kommt das Christuskind // Auf die Erde nieder, // Wo wir Menschen sind;", Author = "Wilhelm Hey" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Christoph_Blocher", Text = "Mit dem Rahmenabkommen wird uns ein Knechtschaftsvertrag aufgedrängt, der die Unabhängigkeit der Schweiz und die direkte Demokratie zerstört.", Author = "Christoph Blocher" },
        new Quote { Id = "https://de.wikiquote.org/wiki/William_Etty", Text = "Wunderbar! Wunderbar, dieser Tod!", Author = "William Etty" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Kleinmut", Text = "Entweder lobt man sich, was Eitelkeit ist - oder tadelt sich, was Kleinmut ist.", Author = "Kleinmut" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Barbara_Ehrenreich", Text = "Wenn du deine Zeit stundenweise verkaufst, bekommst du das Entscheidende nicht gleich mit: daß nämlich das, was du verkaufst, in Wirklichkeit dein Leben ist.", Author = "Barbara Ehrenreich" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Pfarrer", Text = "Ich hab es öfters rühmen hören, // Ein Komödiant könnt einen Pfarrer lehren.", Author = "Pfarrer" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Selbstbehauptung", Text = "Das Ziel des Dialogs ist nicht Unterwerfung und Sieg, auch nicht Selbstbehauptung um jeden Preis, sondern gemeinsame Arbeit in der Methode und in der Sache.", Author = "Selbstbehauptung" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Lerche", Text = "Es war die Nachtigall und nicht die Lerche.", Author = "Lerche" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Ernst_Stadler", Text = "Form ist Wollust, Frieden, himmlisches Genügen, // Doch mich reißt es, Ackerschollen umzupflügen.", Author = "Ernst Stadler" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Robert_Habeck", Text = "Patriotismus, Vaterlandsliebe also, fand ich stets zum Kotzen. Ich wusste mit Deutschland nichts anzufangen und weiß es bis heute nicht.", Author = "Robert Habeck" },
        new Quote { Id = "https://de.wikiquote.org/wiki/John_Quincy_Adams", Text = "Dies ist der letzte Tag auf Erden, ich bin zufrieden.", Author = "John Quincy Adams" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Bernhard_Kellermann", Text = "Geld! Eine Flasche Wein und eine gute Zigarre, das ist alles, was der Mensch braucht. Auf alles andere kann er pfeifen.", Author = "Bernhard Kellermann" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Frevel", Text = "Wer einst als erster sich des Frevels unterfängt, // Dass er dich, Wald, mit hartem Beil bedrängt, // Den soll sein eigner Stab mit hartem Stahl aufspießen, // Und Erysichthon gleich soll er den Hunger büßen.", Author = "Frevel" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Europ%C3%A4er", Text = "Die Muslime begriffen sehr wohl, dass die Europäer sie auf der Ebene der Macht überholt hatten, aber sie konnten nicht begreifen, dass es an der Basis jenes fulminanten Aufstiegs in Europa zu einem Bruch mit dem religiösen Sockel – und das war das eigentliche Werk der Aufklärung – gekommen war", Author = "Europäer" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Tassilo_K%C3%BCpper", Text = "Elitär drückt eine Geisteshaltung aus, etwas, das man für sich in Anspruch nimmt. Wichtig ist jedoch das Handeln der Menschen.", Author = "Tassilo Küpper" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Jugend", Text = "Ach, alles trägt man leicht, ist man nur jung, // Nur jung noch und gesund!", Author = "Jugend" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Vergangenheit", Text = "Aber Gott will auch, daß der Mensch betrachte die vergangenen Zeiten; nicht als Eintagsfliege ohne Zukunft hat Gott den Menschen geschaffen, und wer die ihm geordnete Zukunft genießen will, muß sich dazu stärken an der Vergangenheit.", Author = "Vergangenheit" },
        new Quote { Id = "https://de.wikiquote.org/wiki/%C3%89ric-Emmanuel_Schmitt", Text = "Was du verschenkst, Momo, bleibt immer dein Eigen; was du behältst, ist für immer verloren.", Author = "Éric-Emmanuel Schmitt" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Bauwerk", Text = "Dabei ist meist angenommen worden, dass ein Bauwerk erst anfange ein Kunstwerk zu werden, wenn es mehr tue als dem bloßen Bedürfnis zu genügen.", Author = "Bauwerk" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Brasilianische_Sprichw%C3%B6rter", Text = "Brasilianer schließen die Tür erst nach dem Einbruch ab.", Author = "Brasilianische Sprichwörter" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Walter_Momper", Text = "Wir Deutschen sind jetzt das glücklichste Volk auf der Welt!", Author = "Walter Momper" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Lehm", Text = "Dem Töpfer sah einst im Basar ich zu, // Wie er den Lehm zerstampfte ohne Ruh. // Da hört ich, wie der Lehm ihn leise bat: // Nur sachte, Bruder, einst war ich wie du.", Author = "Lehm" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Georg_Hamann", Text = "Auf Schwächen und Blößen gründet sich die Liebe, und auf diese die Fruchtbarkeit.", Author = "Johann Georg Hamann" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Silber", Text = "Geringer als Gold ist Silber, geringer als die Tugenden das Gold.", Author = "Silber" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Brian_Holm", Text = "Als ich aufhörte, war es, als wäre ich aus dem Gefängnis entlassen worden. Ich konnte wirklich gar nichts außer Radfahren, noch nicht mal eine Waschmaschine bedienen.", Author = "Brian Holm" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Unternehmer", Text = "Das Zeitalter der Fusionen hat Unternehmer als bloße Übernehmer entlarvt. Und mancher hat sich dabei übernommen.", Author = "Unternehmer" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Metrodoros_von_Chios", Text = "Die Erde als die einzige bevölkerte Welt im unendlichen All anzusehen, ist ebenso absurd wie die Behauptung, auf einem ganzen mit Hirse besäten Feld würde nur ein einziges Korn wachsen.", Author = "Metrodoros von Chios" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Philipp_Mi%C3%9Ffelder", Text = "Die Werte der Großeltern sollten wieder eine stärkere Rolle spielen.", Author = "Philipp Mißfelder" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Turm", Text = "Da ich jetzt von weitem die Türme und den blauen Rauch von Nürnberg sah, meinte ich fast, nicht etwa eine einzige Stadt, sondern eine ganze Welt zu sehen.", Author = "Turm" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Warren_Buffett", Text = "„Wenn in Amerika ein Klassenkampf tobt, ist meine Klasse dabei, ihn zu gewinnen.", Author = "Warren Buffett" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Theodor_Mommsen", Text = "Die Kunst des Messens unterwirft dem Menschen die Welt; durch die Kunst des Schreibens hört die Erkenntniss des Menschen auf so vergänglich zu sein wie er selbst ist; sie beide geben dem Menschen, was die Natur ihm versagte, Allmacht und Ewigkeit.", Author = "Theodor Mommsen" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Sully_Prudhomme", Text = "Alle Auflehnung gegen die Natur, gegen die Seinsbedingungen ist unfruchtbar und krankhaft.", Author = "Sully Prudhomme" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Gletscher", Text = "Ruhe, Ruhe, tiefe Ruhe. // Lautlos schlummern Menschen, Tiere. // Nur des Gipfels Gletschertruhe // schüttet talwärts ihre // Wasser.", Author = "Gletscher" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Laotse", Text = "Auch der längste Marsch beginnt mit dem ersten Schritt.", Author = "Laotse" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Kneipe", Text = "Die höre ich in der Kneipe zur Begrüßung: Nabendallerseits.", Author = "Kneipe" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Rebell", Text = "Die Rebellen von gestern sind allzeit die Despoten von heute.", Author = "Rebell" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Kuba", Text = "Amerika wird also, angeführt und aufgeweckt von der kubanischen Revolution, eine Aufgabe von großer, entscheidender Bedeutung haben: die Schaffung eines zweiten, dritten Vietnams.", Author = "Kuba" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Gerald_H%C3%BCther", Text = "Kinder unter Daueraufsicht, die immer nur an der Hand von Erwachsenen umhergeführt werden, gleichen Haustieren, Stalleseln, die das Leben in der Freiheit nicht mehr kennen.", Author = "Gerald Hüther" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Eleganz", Text = "Ab und an sind die Vereinigten Staaten ungefähr so elegant wie ein Elefant beim Spitzentanz.", Author = "Eleganz" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Tugend", Text = "Adel liegt einzig und allein in der Tugend.", Author = "Tugend" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Steven_Weinberg", Text = "Das Bemühen, das Universum zu verstehen, ist eines der ganz wenigen Dinge, die das menschliche Leben ein wenig über die Stufe einer Farce erheben, und gibt ihm etwas von der Anmut der Tragödie.", Author = "Steven Weinberg" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Henry_Adams", Text = "Niemand meint alles was er sagt, und nur wenige sagen alles was sie denken. Worte sind glitschig und Gedanken sind klebrig.", Author = "Henry Adams" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Gottfried_Benn", Text = "Ein Gedicht entsteht überhaupt sehr selten - ein Gedicht wird gemacht.", Author = "Gottfried Benn" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Vergn%C3%BCgen", Text = "Aber in der Beschäftigung selbst Vergnügen finden - dies ist das Geheimnis des Glücklichen!", Author = "Vergnügen" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Wolfgang_Grupp", Text = "Twitter ist für mich einfach nur dumm und die Menschen, die das nutzen, sind für mich Idioten. Haben die Menschen eigentlich nichts Besseres zu tun, als über belanglosen Kram zu schreiben? Wen interessiert das?", Author = "Wolfgang Grupp" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Winkel", Text = "Der Ball sollte genau dahin gehen. Ich habe mir die Kugel vorgelegt und mit Auge in den Winkel geschlenzt. In dem Moment habe ich nicht daran gedacht, daß ich das erste WM-Tor geschossen habe. Für mich war es das Tor des Jahres, es war sogar das Tor meines Lebens.", Author = "Winkel" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Hilfe", Text = "Alles, was man vergessen hat, schreit im Traum um Hilfe.", Author = "Hilfe" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Durchschauen", Text = "Man will zwar andere durchschauen, aber nicht selbst durchschaut werden.", Author = "Durchschauen" },
        new Quote { Id = "https://de.wikiquote.org/wiki/%C3%9Cbertreibung", Text = "Eine Übertreibung ist eine Wahrheit, die ihre Ruhe verloren hat.", Author = "Übertreibung" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Z%C3%B6gern", Text = "Je länger man vor der Tür zögert, desto fremder wird man.", Author = "Zögern" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Maske", Text = "Als wenn ich auf den Maskenball käme // Und gleich die Larve vom Angesicht nähme.", Author = "Maske" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Leer", Text = "In Aurich ist es schaurig, in Leer noch viel mehr, doch will Gott dich strafen, schickt er dich nach Wilhelmshaven!", Author = "Leer" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Genuss", Text = "Beschäftige dich mit Dichtung: Das spornt dir deinen Geist an. Sei es schlichte Prosa: Die labt dich ohne Mühe, oder hohe Verskunst: Sie ist der reinste Genuss.", Author = "Genuss" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Erwartung", Text = "Die bittersten Worte, die Menschen einander sagen, wirken selten so entzweiend wie die unausgesprochenen, die der eine vom andern vergeblich erwartet.", Author = "Erwartung" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Scheuheit", Text = "Unerfahrenheit führt zu Selbstvertrauen, Bildung zu Scheu.", Author = "Scheuheit" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Verfasser", Text = "Der Körper ist der Einband des Geistes, das Gesicht der Titel und das Auge der Name des Verfassers.", Author = "Verfasser" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Michael_Crichton", Text = "Das Vorsorgeprinzip, so es denn korrekt angewendet wird, verbietet das Vorsorgeprinzip. Es ist ein Widerspruch in sich. Das Vorsorgeprinzip kann daher gar nicht hart genug attackiert werden.", Author = "Michael Crichton" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Analyse", Text = "Wer eine Synthese recht prägnant in sich fühlt, der hat eigentlich das Recht zu analysieren, weil er am äußeren Einzelnen sein inneres Ganzes prüft und legitimiert.", Author = "Analyse" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Aachen", Text = "Ich möchte nicht todt und begraben seyn // Als Kaiser zu Aachen im Dome; // Weit lieber lebt' ich als kleinster Poet // Zu Stukkert am Neckarstrome.", Author = "Aachen" },
        new Quote { Id = "https://de.wikiquote.org/wiki/August_Julius_Langbehn", Text = "Das Träumen und Philosophiren hat seine Schattenseiten; wer das zweite Gesicht hat, Dem fehlt mitunter das erste.", Author = "August Julius Langbehn" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Anna_Luise_Karsch", Text = "Du Gott des Krieges, laß die Erde! // Dein Schritt, mit Blut bemerkt, ist fürcherlich, ist schwer, // Verändre doch die schreckliche Gebärde, // Und schüttle länger nicht den Speer.", Author = "Anna Luise Karsch" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Verzweiflung", Text = "Angst vor der Angst zu haben, Angst vor der Verzweiflung zu haben bedeutet, den Erpressungen, die wir nur zu gut kennen, den Weg zu ebnen.", Author = "Verzweiflung" },
        new Quote { Id = "https://de.wikiquote.org/wiki/William_Warren_Bartley", Text = "Denn die Menschen sind dem Problem der Entfremdung noch nicht entfremdet, noch sind sie gleichgültig der Hoffnung gegenüber, die Gleichgültigkeit zu überwinden.", Author = "William Warren Bartley" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Bernhard_Waldenfels", Text = "Wir werden niemals völlig in unserem Leib zur Ruhe kommen, als wären wir Eigentümer unser selbst, doch es kann sehr wohl sein, daß es gerade diese Unruhe ist, die uns lebendig hält.", Author = "Bernhard Waldenfels" },
        new Quote { Id = "https://de.wikiquote.org/wiki/%C3%9Cberlieferung", Text = "Alle echte Überlieferung ist auf den ersten Anblick langweilig, weil und insofern sie fremdartig ist. Sie kündet die Anschauungen und Interessen ihrer Zeit für ihre Zeit und kommt uns gar nicht entgegen, während das moderne Unechte auf uns berechnet, daher pikant und entgegenkommend gemacht ist.", Author = "Überlieferung" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Maria_Callas", Text = "Es gibt Leute, die zum Glücklichsein geboren werden, und andere, die zum Unglücklichsein bestimmt sind. Ich habe einfach Pech gehabt.", Author = "Maria Callas" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Schw%C3%A4che", Text = "Alle Bosheit kommt von der Schwachheit.", Author = "Schwäche" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_von_Sallet", Text = "Oft ist der Weiber Andachtsglut // Nichts weiter als verliebtes Blut.", Author = "Friedrich von Sallet" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Christian_Kern", Text = "Menschen brennen nicht für Kompromisse. Sie brennen für Grundsätze und Haltungen.", Author = "Christian Kern" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Hatun_S%C3%BCr%C3%BCc%C3%BC", Text = "Angst verhindert das Lernen.", Author = "Hatun Sürücü" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Anatole_France", Text = "Alle historischen Bücher, die keine Lügen enthalten, sind schrecklich langweilig.", Author = "Anatole France" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Publilius_Syrus", Text = "Niemandem und jedem zu glauben ist beides ein Laster.", Author = "Publilius Syrus" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Wladimir_Wladimirowitsch_Putin", Text = "Und wenn wir uns jetzt damit beschäftigen, unser Leben zu verteidigen, will man uns dafür dann die Wurst wegnehmen? Was für eine Wahl haben wir? Zwischen Wurst und Leben. Wir wählen das Leben!", Author = "Wladimir Wladimirowitsch Putin" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Entdecker", Text = "Welcher Entdecker hat das schon bemessen, wie weit sich die äußersten Vorgebirge der Möglichkeit ins Meer der Unmöglichkeit hinein erstrecken?", Author = "Entdecker" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Hans_Fallada", Text = "Denn so sind die Menschen: eine gemeinsame Furcht führt sie leichter zusammen als eine gemeinsame Liebe.", Author = "Hans Fallada" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Anton_Bruckner", Text = "Daß es Bruckner gegeben hat, ist für mich das größte Geschenk Gottes.", Author = "Anton Bruckner" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Oliviero_Toscani", Text = "Betrachten ist ein schöpferischer Akt.", Author = "Oliviero Toscani" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Giora_Feidman", Text = "„Musik beginnt nicht mit dem ersten Ton, sondern mit der Stille davor. Und sie endet nicht mit dem letzten Ton, sondern mit dem Klang der Stille danach.", Author = "Giora Feidman" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Kirk_Douglas", Text = "Romantik fängt mit 80 an.", Author = "Kirk Douglas" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Bakterie", Text = "Es ist mir nämlich gelungen, die Bakterien mit solchen Farbstoffen zu imprägnieren, welche ihre Form nicht verändern und sie ganz ausserordentlich deutlich erscheinen lassen.", Author = "Bakterie" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Edmund_Burke", Text = "Das Böse triumphiert allein dadurch, dass gute Menschen nichts unternehmen. - Edmund Burke", Author = "Edmund Burke" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Ludwig_Bamberger", Text = "Wer die Parlamente einsetzt, ehe das Reich der Freiheit im Fundament gegründet ist, der bahnt nicht dem Fortschritt, sondern dem Verrat den Weg.", Author = "Ludwig Bamberger" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Tim_Berners-Lee", Text = "Die Wikis sind ein großartiges Zeichen dafür, wie Menschen kreativ werden wollen.", Author = "Tim Berners-Lee" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Samuel_Smiles", Text = "Alles gelingt, was man mit rechtem Eifer angreift.", Author = "Samuel Smiles" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Ernst_Mach", Text = "Die Brücke zwischen der Physik im weitesten Sinne und der naturwissenschaftlichen Psychologie bilden eben dieselben Elemente, welche je nach dem untersuchten Zusammenhang physische oder psychische Objecte sind.", Author = "Ernst Mach" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Paul_Sethe", Text = "Ich weiß, dass es im deutschen Pressewesen Oasen gibt, in denen noch die Luft der Freiheit weht. Ich bin glücklich, in einer solchen Oase zu leben. Aber wie viele von meinen Kollegen können das von sich sagen?", Author = "Paul Sethe" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Til_Schweiger", Text = "Als Mann eine Frau zu verstehen, ist genauso unmöglich, wie als Frau einen Mann zu verstehen. Deswegen haben wir doch die ganzen Probleme.", Author = "Til Schweiger" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Tacitus", Text = "Sie schaffen eine Wüste und nennen das Frieden", Author = "Tacitus" }
    };
}